  'pol.stat.pm': { en: `Federal Council salary + CHF 12,000 tax-free`, nl: `Loon van de Bondsraad + CHF 12.000 belastingvrij`, fr: `Traitement du Conseil fédéral + 12 000 CHF exonérés` },
