  'pol.stat.senator': { en: `2023 average taxable pay, without tax-free allowances`, nl: `Gemiddeld belastbaar inkomen 2023, zonder belastingvrije vergoedingen`, fr: `Revenu imposable moyen 2023, hors indemnités exonérées` },
